# owner: platform
import unittest
from datetime import date

from rosterkit.models import Mark, Student
from rosterkit.notices import absence_notice

STUDENT = Student("1", "Doe", "Ann", "A")

def mark(day, status="absent", sid="1"):
    return Mark(sid, date(2026, 9, day), status)

class NoticeTests(unittest.TestCase):
    def test_dates_in_order(self):
        marks = [mark(4), mark(2), mark(3, "present")]
        self.assertEqual(
            absence_notice(STUDENT, marks),
            "Ann Doe missed 2 days: "
            "2026-09-02, 2026-09-04."
        )

    def test_single_day(self):
        text = absence_notice(STUDENT, [mark(2)])
        self.assertIn("1 day:", text)

    def test_other_student(self):
        with self.assertRaises(ValueError):
            absence_notice(STUDENT, [mark(2, sid="2")])

    def test_no_absences(self):
        with self.assertRaises(ValueError):
            absence_notice(STUDENT, [mark(2, "late")])

if __name__ == "__main__":
    unittest.main()
